FUNCTION UNDER TEST:
Name: trie_get_prefix_node
Signature: int trie_get_prefix_node( struct trie * trie, const char *prefix, struct trie ** result )
Description: /**
 * @brief Find the trie node corresponding to a prefix string.
 *
 * Searches the trie for the node representing the end of the given prefix.
 * The function validates its inputs and delegates the search to trie_search.
 *
 * @param trie Root of the trie to search. Must not be NULL.
 * @param prefix String to locate within the trie. Must not be NULL.
 * @param result Pointer where the found node will be stored. Must not be NULL.
 *               On success, contains the node where the prefix ends, or NULL
 *               if the prefix is not present in the trie.
 *
 * @return 0 on successful search completion, -1 on invalid input parameters.
 *
 * @note The prefix length is internally limited to 100 characters.
 * @see trie_search
 */
Dependencies: trie_search

FUNCTION IMPLEMENTATION (REFERENCE ONLY - do NOT copy into test):
```c
// C program for the function called trie_get_prefix_node
// Contains target function implementation and dependency signatures

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct trie {
    struct trie *children[ALPHABET_SIZE];
    bool end_of_word;
};

// Forward declarations for dependency functions
int trie_search(
    struct trie * trie,
    char *word,
    unsigned word_len,
    struct trie ** result
);

// Target function implementation
int trie_get_prefix_node(
    struct trie * trie,
    const char *prefix,
    struct trie ** result
)
{
    if (NULL == trie || NULL == prefix || NULL == result) {
        return -1;
    }
    return trie_search(trie, (char *)prefix, strnlen(prefix, 100), result);
}

